mapper.select:
SELECT 
FROM patient_user_relation pur
INNER JOIN patient p ON p.id = pur.patient_id AND p.deleted_at IS NULL
WHERE pur.user_id = #{userId}
  AND pur.patient_id = #{patientId}
  AND pur.deleted_at IS NULL

SELECT EXISTS (
    SELECT 1
    FROM patient_user_relation pur
    INNER JOIN patient p ON p.id = pur.patient_id AND p.deleted_at IS NULL
    WHERE pur.user_id = #{userId}
      AND pur.deleted_at IS NULL
      AND p.id_card_ciphertext = #{idCardNo}

          AND p.id <> #{excludePatientId}

)

mapper.update:
UPDATE patient_user_relation
SET deleted_at = #{deletedAt},
    updated_at = #{deletedAt}
WHERE id = #{relationId}
  AND user_id = #{userId}
  AND deleted_at IS NULL
